function initMoveToFolderAgainMenu(aMenuItem) {
  const lastFolderURI = Services.prefs.getStringPref(
    "mail.last_msg_movecopy_target_uri"
  );

  if (!lastFolderURI) {
    return;
  }
  const destMsgFolder = MailUtils.getExistingFolder(lastFolderURI);
  if (!destMsgFolder) {
    return;
  }
  document.l10n.setAttributes(
    aMenuItem,
    Services.prefs.getBoolPref("mail.last_msg_movecopy_was_move")
      ? "menu-move-to-folder-again"
      : "menu-copy-to-folder-again",
    {
      folderName: destMsgFolder.localizedName,
    }
  );
  aMenuItem.setAttribute(
    "tooltiptext",
    `${destMsgFolder.prettyPath} – ${destMsgFolder.server.prettyName}`
  );
}
